import sqlite3
from datetime import datetime, timedelta

import stripe

DB_PATH = "/var/lib/smarthub/hub.db"
PLAN_PRICES = {"basic": 299, "plus": 699, "pro": 1299}
PLAN_DAYS = {"basic": 7, "plus": 30, "pro": 60}


def _save_subscription(camera_id, plan, charge_id):
    expires = (datetime.utcnow() + timedelta(days=30)).isoformat()
    conn = sqlite3.connect(DB_PATH)
    conn.execute(
        "UPDATE cameras SET plan = ?, retention_days = ?, plan_expires = ?, last_charge_id = ? WHERE id = ?",
        (plan, PLAN_DAYS[plan], expires, charge_id, camera_id),
    )
    conn.commit()
    conn.close()
    return expires


def purchase_camera_cloud_plan(camera_id: str, customer_id: str, plan: str) -> dict:
    if plan not in PLAN_PRICES:
        return {"error": "unknown plan", "valid_plans": list(PLAN_PRICES)}
    intent = stripe.PaymentIntent.create(
        amount=PLAN_PRICES[plan],
        currency="usd",
        customer=customer_id,
        confirm=True,
        off_session=True,
        description=f"Cloud plan {plan} for camera {camera_id}",
    )
    if intent.status != "succeeded":
        return {"error": "payment failed", "status": intent.status}
    expires = _save_subscription(camera_id, plan, intent.id)
    return {
        "camera_id": camera_id,
        "plan": plan,
        "charged_cents": PLAN_PRICES[plan],
        "charge_id": intent.id,
        "expires": expires,
    }
